/*
 * A117899  Expansion of (1 + 2*x + 5*x^2 + 3*x^3 + 2*x^4)/(1-x^3)^2.
 * https://oeis.org/A117899
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = 2*a(n-3) - a(n-6) for n ≥ 6, a(0) = 1, a(1) = 2, a(2) =
 *            5, a(3) = 5, a(4) = 6, a(5) = 10 (generated by
 *            (1+2x+5x²+3x³+2x⁴)/(1−x³)²)
 * Range:     u8 n <= 154, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache to allow out‑of‑order calls */
    static seq_t *cache = NULL;
    static size_t cache_size = 0;   /* allocated length */
    static idx_t max_index = 5;     /* last computed index */

    /* initialise cache with first six terms on first call */
    if (cache == NULL) {
        cache_size = 6;
        cache = (seq_t *)malloc(cache_size * sizeof(seq_t));
        if (!cache) return (seq_t)0;            /* allocation failed */
        cache[0] = (seq_t)1;
        cache[1] = (seq_t)2;
        cache[2] = (seq_t)5;
        cache[3] = (seq_t)5;
        cache[4] = (seq_t)6;
        cache[5] = (seq_t)10;
    }

    /* extend cache up to requested index */
    if (n > max_index) {
        size_t new_size = (size_t)(n + 1);
        seq_t *tmp = (seq_t *)realloc(cache, new_size * sizeof(seq_t));
        if (!tmp) return (seq_t)0;              /* allocation failed */
        cache = tmp;
        cache_size = new_size;

        /* compute missing terms using recurrence */
        for (idx_t i = max_index + 1; i <= n; ++i) {
            /* a(i) = 2*a(i-3) - a(i-6)  (i >= 6) */
            cache[i] = ((seq_t)2) * cache[i - 3] - cache[i - 6];
        }
        max_index = n;
    }

    return cache[n];
}
